SET search_path = '';

-- Update type constraint
ALTER TABLE public.modules_directory DROP CONSTRAINT IF EXISTS modules_directory_type_check;
ALTER TABLE public.modules_directory ADD CONSTRAINT modules_directory_type_check CHECK (type IN ('ui', 'agent', 'mcp_server', 'ai_skill', 'open_source_app'));

ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  github_url = EXCLUDED.github_url,
  json_config = EXCLUDED.json_config,
  type = EXCLUDED.type,
  is_free = EXCLUDED.is_free;
